<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { anularIngreso, guardarIngreso, listarIngresos, obtenerIngreso, urlNotaIngreso } from '../services/ingresos'
import type { DetalleIngreso, IngresoAlmacen, PeriodoAlmacen, TipoIngreso } from '../interfaces/ingresos.interface'

const rows=ref<IngresoAlmacen[]>([]),tipos=ref<TipoIngreso[]>([]),periodo=ref<PeriodoAlmacen|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),detail=ref<IngresoAlmacen|null>(null),modal=ref(false)
const filters=reactive({criterio:'',tipo_id:'',desde:'',hasta:''})
const form=reactive({tipo_id:0,fecha_operacion:'',documento:'',referencia:'',observacion:'',detalles:[] as Array<{item_id:number;item:string;cantidad:number;precio_unitario:number}>})
const formTotal=computed(()=>form.detalles.reduce((sum,item)=>sum+item.cantidad*item.precio_unitario,0))
async function load(next=1){page.value=next;loading.value=true;error.value='';try{const res=await listarIngresos({...filters,page:next});rows.value=res.data;tipos.value=res.tipos;periodo.value=res.periodo;total.value=res.total;lastPage.value=res.last_page}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,{criterio:'',tipo_id:'',desde:'',hasta:''});load(1)}
function openCreate(){if(periodo.value&&!periodo.value.abierto){error.value='El periodo de almacén se encuentra cerrado.';return}Object.assign(form,{tipo_id:tipos.value[0]?.id||0,fecha_operacion:periodo.value?.dia_vigente||new Date().toISOString().slice(0,10),documento:'',referencia:'',observacion:'',detalles:[]});addItem();modal.value=true}
function addItem(){form.detalles.push({item_id:0,item:'',cantidad:1,precio_unitario:0})}
function validate(){if(!form.tipo_id)return 'Seleccione el tipo de ingreso.';if(!form.fecha_operacion)return 'Ingrese la fecha de operación.';if(!form.detalles.length)return 'Agregue al menos un ítem.';if(form.detalles.some(x=>!x.item_id||x.cantidad<=0||x.precio_unitario<0))return 'Complete correctamente todos los ítems.';return ''}
async function save(){const issue=validate();if(issue){error.value=issue;return}saving.value=true;try{await guardarIngreso({...form,detalles:form.detalles.map(({item_id,cantidad,precio_unitario})=>({item_id,cantidad,precio_unitario}))});modal.value=false;success.value='Ingreso registrado correctamente.';await load(1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function show(item:IngresoAlmacen){try{detail.value=await obtenerIngreso(item.id)}catch(e){error.value=message(e)}}
async function cancel(item:IngresoAlmacen){if(!canCancel(item))return;const motivo=prompt(`Motivo de anulación del ingreso #${item.id}:`)?.trim();if(!motivo)return;if(!confirm('La anulación revertirá el stock asociado. ¿Desea continuar?'))return;try{await anularIngreso(item.id,item.almacen_id,motivo);success.value='Ingreso anulado y stock revertido correctamente.';await load(page.value)}catch(e){error.value=message(e)}}
function canCancel(item:IngresoAlmacen){if(item.anulado||!periodo.value?.abierto)return false;const date=new Date(`${item.fecha_operacion}T00:00:00`);return date>=new Date(`${periodo.value.fecha_inicio}T00:00:00`)&&date<=new Date(`${periodo.value.fecha_fin}T23:59:59`)}
function money(value=0){return new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(value)}
function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}
onMounted(()=>load())
</script>

<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Almacén / Ingresos</nav>
<header class="hero"><div class="mark">IN</div><div><small>MIA · ALMACÉN</small><h1>Ingresos de almacén</h1><p>Consulta y registra notas de ingreso de bienes y materiales.</p></div><div class="period"><small>PERIODO VIGENTE</small><b>{{periodo?.nombre||'Sin periodo'}}</b><span :class="{closed:!periodo?.abierto}">{{periodo?.abierto?'Abierto':'Cerrado'}}</span></div><button :disabled="periodo?.abierto===false" @click="openCreate">+ Nuevo ingreso</button></header>
<p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p>
<section class="filters"><label>N° ingreso<input v-model.trim="filters.criterio" placeholder="Número de nota" @keyup.enter="load(1)"></label><label>Desde<input v-model="filters.desde" type="date"></label><label>Hasta<input v-model="filters.hasta" type="date"></label><label>Tipo de documento<select v-model="filters.tipo_id"><option value="">Todos</option><option v-for="tipo in tipos" :key="tipo.id" :value="tipo.id">{{tipo.nombre}}</option></select></label><button @click="load(1)">Buscar</button><button class="soft" @click="clear">Limpiar</button></section>
<div v-if="loading" class="empty">Cargando ingresos…</div><div v-else-if="!rows.length" class="empty">No se encontraron movimientos de ingreso.</div>
<section v-else class="cards"><article v-for="item in rows" :key="item.id" :class="{cancelled:item.anulado}"><header><div class="icon">↘</div><div><small>NOTA DE INGRESO</small><h2>Ingreso #{{item.id}}</h2></div><span>{{item.anulado?'ANULADO':'VIGENTE'}}</span></header><dl><div><dt>Tipo</dt><dd>{{item.tipo}}</dd></div><div><dt>Fecha</dt><dd>{{item.fecha_operacion}}</dd></div><div><dt>Almacén</dt><dd>{{item.almacen}}</dd></div><div><dt>Ítems</dt><dd>{{item.items_count}}</dd></div><div><dt>Valor</dt><dd>{{money(item.valor_total)}}</dd></div></dl><footer><button @click="show(item)">Ver detalle</button><a :href="urlNotaIngreso(item.id,item.almacen_id)" target="_blank">Imprimir nota</a><button class="danger" :disabled="!canCancel(item)" @click="cancel(item)">Anular</button></footer></article></section>
<footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}} · {{total}} registros</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="dialog detail"><header><div><small>DETALLE DE MOVIMIENTO</small><h2>Ingreso #{{detail.id}}</h2></div><button @click="detail=null">×</button></header><p>{{detail.tipo}} · {{detail.fecha_operacion}} · {{detail.almacen}}</p><table><thead><tr><th>Ítem</th><th>Unidad</th><th>Cantidad</th><th>P. unitario</th><th>Total</th></tr></thead><tbody><tr v-for="line in (detail.detalles||[])" :key="line.id"><td>{{line.item}}</td><td>{{line.unidad}}</td><td>{{line.cantidad}}</td><td>{{money(line.precio_unitario)}}</td><td>{{money(line.valor_total)}}</td></tr></tbody></table><footer><b>Total: {{money(detail.valor_total)}}</b><button @click="detail=null">Cerrar</button></footer></section></div>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>NUEVO MOVIMIENTO</small><h2>Registrar ingreso</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Tipo de ingreso *<select v-model.number="form.tipo_id"><option :value="0">Seleccione</option><option v-for="tipo in tipos" :key="tipo.id" :value="tipo.id">{{tipo.nombre}}</option></select></label><label>Fecha de operación *<input v-model="form.fecha_operacion" type="date"></label><label>Documento<input v-model.trim="form.documento"></label><label>Referencia<input v-model.trim="form.referencia"></label></div><label>Observación<textarea v-model.trim="form.observacion" rows="2"></textarea></label><div class="lines"><header><b>Detalle de ítems</b><button type="button" @click="addItem">+ Agregar</button></header><div v-for="(line,index) in form.detalles" :key="index" class="line"><input v-model.number="line.item_id" type="number" min="1" placeholder="ID ítem"><input v-model.trim="line.item" placeholder="Descripción referencial"><input v-model.number="line.cantidad" type="number" min="0.0001" step="0.0001" placeholder="Cantidad"><input v-model.number="line.precio_unitario" type="number" min="0" step="0.01" placeholder="Precio"><b>{{money(line.cantidad*line.precio_unitario)}}</b><button type="button" @click="form.detalles.splice(index,1)">×</button></div></div><footer><b>Total {{money(formTotal)}}</b><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Registrar ingreso'}}</button></footer></form></div></div></template>

<style scoped>
.page{--accent:#d64f83;color:#34464f}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark,.icon{display:grid;place-items:center;color:#fff;background:var(--accent);font-weight:700}.mark{width:50px;height:50px;border-radius:10px;font-size:.65rem}.hero small,.cards small,.dialog small{color:var(--accent);font-size:.5rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero>button,.filters button,.pages button,.dialog button{padding:8px 10px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.55rem}.hero>button:disabled{opacity:.5}.period{margin-left:auto;padding:7px 10px;border-radius:7px;background:#f5f7f8}.period>*{display:block}.period b{font-size:.6rem}.period span{color:#23855d;font-size:.5rem}.period span.closed{color:#b34449}.flash{padding:9px;border-radius:7px;color:#287052;background:#edf9f3;font-size:.6rem}.flash.error{color:#a64046;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:grid;grid-template-columns:1fr 1fr 1fr 1.4fr auto auto;align-items:end;gap:7px;border-radius:9px;background:#fff}label{display:block;font-size:.53rem}input,select,textarea{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d9e0e3;border-radius:6px;font:inherit;font-size:.58rem}.soft{color:#64727a!important;background:#edf1f3!important}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.62rem}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{padding:13px;border:1px solid #e0e5e7;border-top:4px solid #32a5a6;border-radius:9px;background:#fff}.cards article.cancelled{opacity:.68;border-top-color:#c34b52}.cards article>header{display:flex;align-items:center;gap:8px}.icon{width:35px;height:35px;border-radius:8px;background:#32a5a6}.cards h2{margin:2px 0;font-size:.68rem}.cards header span{margin-left:auto;padding:4px 7px;border-radius:10px;color:#277254;background:#e7f7ef;font-size:.46rem}.cancelled header span{color:#a33f45;background:#fdeced}.cards dl{margin:10px 0}.cards dl div{padding:5px 0;display:flex;border-bottom:1px solid #edf0f1;font-size:.52rem}.cards dd{margin-left:auto;text-align:right}.cards dt{color:#78868d}.cards footer{display:flex;align-items:center;gap:6px}.cards footer button,.cards footer a{border:0;color:#297f83;background:none;text-decoration:none;font-size:.5rem}.cards footer .danger{margin-left:auto;color:#bd4149}.cards footer button:disabled{color:#afb6b9}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.53rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(900px,100%);max-height:90vh;overflow:auto;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog h2{margin:2px 0 13px;font-size:1rem}.dialog>header button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.lines{margin:12px 0;padding:10px;border-radius:8px;background:#f6f8f9}.lines>header{display:flex;align-items:center}.lines>header button{margin-left:auto}.line{margin-top:6px;display:grid;grid-template-columns:.6fr 1.7fr .7fr .7fr .7fr auto;align-items:center;gap:5px}.line input{margin:0}.line b{font-size:.52rem}.line>button{padding:6px;color:#b13e45;background:#fae8e9}.dialog>footer{display:flex;justify-content:flex-end;align-items:center;gap:7px}.dialog>footer b{margin-right:auto;font-size:.65rem}.detail p{font-size:.58rem}table{width:100%;border-collapse:collapse;font-size:.54rem}th,td{padding:8px;border-bottom:1px solid #e5e9eb;text-align:left}th{color:#68767d;background:#f4f6f7}@media(max-width:850px){.hero{flex-wrap:wrap}.period{margin-left:0}.filters{grid-template-columns:1fr 1fr}.cards{grid-template-columns:1fr}.grid{grid-template-columns:1fr}.line{grid-template-columns:1fr 1fr}.dialog{padding:14px}}
</style>
